const convs = $input.all();
const hoje = $now.setZone('Europe/Lisbon').toFormat('yyyy-MM-dd');
const MAX_CONV = 60;
const MAX_CHARS = 4000;

let bloco = '';
let n = 0;
for (const item of convs) {
  const j = item.json || {};
  const concat = (j.concat_Messages || '').toString();
  if (concat.trim().length < 5) continue;
  n++;
  if (n > MAX_CONV) { n = MAX_CONV; break; }
  const nome = j.Name || j.nome || j['Nome'] || j['Airtable ID'] || ('Conversa ' + n);
  const evento = j.event_name || j.Evento || j['Nome do Evento'] || '';
  const idioma = j.Idioma || j.Language || j.idioma || '';
  const c = concat.length > MAX_CHARS ? (concat.slice(0, MAX_CHARS) + ' ...[truncado]') : concat;
  const head = 'CONVERSA ' + n + ': ' + nome + (evento ? ' | ' + evento : '') + (idioma ? ' | ' + idioma : '');
  bloco += '\n\n===== ' + head + ' =====\n' + c;
}

const prompt = [
'Es o auditor de qualidade do atendimento SDR do Ary. Recebes TODAS as conversas entre leads e o bot/assistente que se moveram hoje (' + hoje + '). Total: ' + n + ' conversas.',
'',
'Analisa cada conversa e procura tres familias de sinal:',
'1. ERROS DO BOT: respostas duplicadas ou vazias, loops (repetir a mesma pergunta), fallbacks genericos (nao entendeu), fluxo interrompido a meio da qualificacao.',
'2. ANOMALIAS DE ATENDIMENTO: lead pediu humano e ninguem assumiu, frustracao ou sentimento negativo, abandono apos uma pergunta especifica, lead respondeu e o bot nao seguiu.',
'3. SINAIS DE NEGOCIO: objecoes recorrentes (preco, confianca, hesitacao), perguntas que o bot nao soube responder, motivos de cancelamento ou no-show, qualificacao errada.',
'',
'Produz um relatorio acionavel em PT-BR, maximo 400 palavras, neste formato exato:',
'RESUMO: X conversas | Y com anomalia',
'ANOMALIAS (por conversa): - [nome] - [o que aconteceu] - gravidade (baixa/media/alta)',
'PADROES: 2 a 4 bullets com os padroes agregados do dia',
'MELHORIAS NO WORKFLOW: 2 a 4 propostas concretas (ex: adicionar resposta sobre honorarios ao prompt do bot; encurtar a pergunta que causa abandono; detectar pedido de humano e escalar)',
'DECIDE: apenas o que precisa mesmo da decisao do Ary',
'',
'Regras: se uma conversa nao tem anomalia relevante, NAO a listes. Cita um excerto curto quando ajudar. Se n = 0, responde apenas: Sem conversas movimentadas hoje.',
'',
'=== CONVERSAS DO DIA ===' + (bloco || '\n(nenhuma)')
].join('\n');

return [{ json: { prompt: prompt, timeout: 300000, total: n } }];

const bridgeOutput = $input.first().json;
const out = bridgeOutput.output || '';

// Detect silent failures of Claude Bridge that return HTTP 200 with bad content:
// - OAuth expired: "Not logged in - Please run /login"
// - Output truncated/empty: legitimate Night Shift is typically >100 chars
const oauthDead = /not logged in|please run \/login|please log in/i.test(out);
const tooShort = out.trim().length < 30;

if (out.length > 10 && !oauthDead && !tooShort) {
  return [{ json: { output: out, elapsed_s: bridgeOutput.elapsed_s || 0, fallback: false, prompt: '' } }];
}

const prompt = $('Build Audit Prompt').first().json.prompt || '';
return [{ json: { output: '', elapsed_s: 0, fallback: true, prompt: prompt } }];

const response = $input.first().json;
const text = response.content && response.content[0] ? response.content[0].text : JSON.stringify(response);
return [{ json: { output: text + '\n\n⚠️ Gerado via Haiku API (fallback — Claude Bridge indisponivel)', elapsed_s: 0 } }];

